-- Product analytics: the users of an app, and what they did and when. Times are text, YYYY-MM-DD HH:MM:SS.
-- Made by scripts/dev/make-sql-data.py: do not edit by hand.

CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  plan TEXT NOT NULL,  -- free, pro or team
  signed_up TEXT NOT NULL
);

CREATE TABLE events (
  id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id),
  name TEXT NOT NULL,  -- signup, login, view_pricing, start_trial, purchase or export
  at TEXT NOT NULL  -- YYYY-MM-DD HH:MM:SS
);
